"use client";
import{useCallback,useEffect,useState}from"react";import{AppShell}from"../ui/app-shell";import{usePlayerData}from"../../lib/use-player-data";import{getSupabaseBrowserClient}from"../../lib/supabase/client";import"../release.css";
type Release={id:string;version_label:string;release_name:string;status:string;release_notes:string;rollback_plan:string;approved_at:string|null;created_at:string};type Check={id:string;label:string;category:string;required:boolean;status:string;evidence_note:string};type Cohort={id:string;cohort_name:string;sequence_number:number;planned_players:number;status:string;start_after:string|null;success_note:string};type Incident={id:string;severity:string;summary:string;detail:string;status:string;rollback_required:boolean;created_at:string};type Ready={required_total:number;required_passed:number;failed_checks:number;completed_pilots:number;pilot_blockers:number;open_critical_incidents:number;recent_backups:number;ready_to_approve:boolean};
export default function ReleasePage(){const{profile}=usePlayerData();const coach=profile?.role==="coach"||profile?.role==="admin";const[releases,setReleases]=useState<Release[]>([]),[selected,setSelected]=useState(""),[checks,setChecks]=useState<Check[]>([]),[cohorts,setCohorts]=useState<Cohort[]>([]),[incidents,setIncidents]=useState<Incident[]>([]),[ready,setReady]=useState<Ready|null>(null),[message,setMessage]=useState(""),[busy,setBusy]=useState(false),[candidate,setCandidate]=useState({version:"1.0.0",name:"Vector Golf Performance production release"}),[cohort,setCohort]=useState({name:"Cohort 1 · Supported launch",players:5,start:""}),[incident,setIncident]=useState({severity:"medium",summary:"",detail:"",rollback_required:false});
 const loadReleases=useCallback(async()=>{const sb=getSupabaseBrowserClient();if(!sb||!coach)return;const{data,error}=await sb.from("release_records").select("*").order("created_at",{ascending:false});if(error){setMessage(error.message);return}setReleases((data||[])as Release[]);setSelected(current=>current||data?.[0]?.id||"")},[coach]);
 const loadDetail=useCallback(async()=>{const sb=getSupabaseBrowserClient();if(!sb||!selected)return;const[{data:c},{data:o},{data:i},{data:r}]=await Promise.all([sb.from("release_check_items").select("*").eq("release_id",selected).order("category"),sb.from("rollout_cohorts").select("*").eq("release_id",selected).order("sequence_number"),sb.from("release_incidents").select("*").eq("release_id",selected).order("created_at",{ascending:false}),sb.rpc("release_readiness",{target_release:selected})]);setChecks((c||[])as Check[]);setCohorts((o||[])as Cohort[]);setIncidents((i||[])as Incident[]);setReady(r as Ready)},[selected]);useEffect(()=>{const timer=setTimeout(()=>void loadReleases(),0);return()=>clearTimeout(timer)},[loadReleases]);useEffect(()=>{const timer=setTimeout(()=>void loadDetail(),0);return()=>clearTimeout(timer)},[loadDetail]);
 const createRelease=async()=>{const sb=getSupabaseBrowserClient();if(!sb)return;setBusy(true);const{data,error}=await sb.rpc("create_release_candidate",{candidate_version:candidate.version,candidate_name:candidate.name});setBusy(false);setMessage(error?error.message:"Release candidate created with eight required gates.");if(!error){await loadReleases();setSelected(data as string)}};
 const updateCheck=async(item:Check,status:string)=>{const sb=getSupabaseBrowserClient();if(!sb||!profile)return;await sb.from("release_check_items").update({status,checked_by:profile.id,checked_at:new Date().toISOString(),evidence_note:item.evidence_note||`Confirmed during Package 7H.4 release review.`}).eq("id",item.id);await loadDetail()};
 const approve=async()=>{const sb=getSupabaseBrowserClient();if(!sb)return;setBusy(true);const{error}=await sb.rpc("approve_release",{target_release:selected});setBusy(false);setMessage(error?error.message:"Release approved. Begin with the smallest supported cohort.");await loadReleases();await loadDetail()};
 const addCohort=async()=>{const sb=getSupabaseBrowserClient();if(!sb||!selected)return;const{error}=await sb.from("rollout_cohorts").insert({release_id:selected,cohort_name:cohort.name,planned_players:cohort.players,start_after:cohort.start||null,sequence_number:cohorts.length+1});setMessage(error?error.message:"Rollout cohort added.");if(!error){setCohort({name:`Cohort ${cohorts.length+2}`,players:10,start:""});await loadDetail()}};
 const updateCohort=async(id:string,status:string)=>{const sb=getSupabaseBrowserClient();if(!sb)return;await sb.from("rollout_cohorts").update({status,started_at:status==="active"?new Date().toISOString():undefined,completed_at:status==="completed"?new Date().toISOString():undefined}).eq("id",id);if(status==="active")await sb.from("release_records").update({status:"rolling_out",updated_at:new Date().toISOString()}).eq("id",selected);await loadDetail();await loadReleases()};
 const addIncident=async()=>{const sb=getSupabaseBrowserClient();if(!sb||!profile||!selected||!incident.summary.trim())return;const{error}=await sb.from("release_incidents").insert({...incident,release_id:selected,reported_by:profile.id});if(!error&&(incident.severity==="critical"||incident.rollback_required))await sb.from("release_records").update({status:"paused",updated_at:new Date().toISOString()}).eq("id",selected);setMessage(error?error.message:"Incident recorded; critical or rollback events pause the release.");if(!error){setIncident({severity:"medium",summary:"",detail:"",rollback_required:false});await loadDetail();await loadReleases()}};
 const rollback=async()=>{const sb=getSupabaseBrowserClient();if(!sb)return;await sb.from("release_records").update({status:"rolled_back",updated_at:new Date().toISOString()}).eq("id",selected);setMessage("Release marked rolled back. Follow the recorded rollback plan before any new cohort.");await loadReleases()};const current=releases.find(r=>r.id===selected);
 if(!coach)return <AppShell active="release"><section className="release-empty"><h1>Coach access required</h1><p>Production release controls are restricted to coaches and administrators.</p></section></AppShell>;
 return <AppShell active="release"><header className="page-heading"><div><p className="eyebrow">Package 7H.4 · Production readiness</p><h1>Release deliberately. Expand with evidence.</h1><p>Complete every production gate, approve one immutable decision and widen access through monitored cohorts.</p></div></header>{message&&<div className="success-banner" role="status">{message}</div>}<section className="release-create"><div><label>Version<input value={candidate.version} onChange={e=>setCandidate({...candidate,version:e.target.value})}/></label><label>Release name<input value={candidate.name} onChange={e=>setCandidate({...candidate,name:e.target.value})}/></label><button className="primary-action" disabled={busy||!candidate.version.trim()} onClick={createRelease}>Create candidate</button></div>{releases.length>0&&<label>Release history<select value={selected} onChange={e=>setSelected(e.target.value)}>{releases.map(r=><option key={r.id} value={r.id}>{r.version_label} · {r.status}</option>)}</select></label>}</section>{current&&<><section className="release-status"><div><span className={`release-pill ${current.status}`}>{current.status.replace("_"," ")}</span><h2>{current.version_label} · {current.release_name}</h2><p>{current.release_notes}</p></div><div className="release-actions"><button className="primary-action" disabled={!ready?.ready_to_approve||current.status!=="candidate"||busy} onClick={approve}>Approve release</button><button disabled={current.status==="rolled_back"} onClick={rollback}>Mark rolled back</button></div></section><section className="release-metrics"><article><strong>{ready?.required_passed||0}/{ready?.required_total||0}</strong><span>required gates</span></article><article><strong>{ready?.completed_pilots||0}</strong><span>completed pilots</span></article><article className={ready?.pilot_blockers?"alert":""}><strong>{ready?.pilot_blockers||0}</strong><span>pilot blockers</span></article><article className={ready?.open_critical_incidents?"alert":""}><strong>{ready?.open_critical_incidents||0}</strong><span>critical incidents</span></article><article><strong>{ready?.recent_backups||0}</strong><span>recent snapshots</span></article></section><section className="release-panel"><div className="section-heading"><div><p className="eyebrow">Release gates</p><h2>Required evidence</h2></div><span>{ready?.ready_to_approve?"Ready for sign-off":"Approval locked"}</span></div><div className="check-list">{checks.map(c=><article key={c.id}><div><small>{c.category}</small><strong>{c.label}</strong><input aria-label={`Evidence for ${c.label}`} placeholder="Evidence note" value={c.evidence_note} onChange={e=>setChecks(items=>items.map(x=>x.id===c.id?{...x,evidence_note:e.target.value}:x))}/></div><div><button className={c.status==="passed"?"selected":""} onClick={()=>updateCheck(c,"passed")}>Pass</button><button className={c.status==="failed"?"failed selected":"failed"} onClick={()=>updateCheck(c,"failed")}>Fail</button></div></article>)}</div></section><div className="release-grid"><section className="release-panel"><p className="eyebrow">Controlled expansion</p><h2>Rollout cohorts</h2><div className="cohort-form"><input aria-label="Cohort name" value={cohort.name} onChange={e=>setCohort({...cohort,name:e.target.value})}/><input aria-label="Number of players" type="number" min="0" value={cohort.players} onChange={e=>setCohort({...cohort,players:Number(e.target.value)})}/><input aria-label="Start after" type="date" value={cohort.start} onChange={e=>setCohort({...cohort,start:e.target.value})}/><button onClick={addCohort}>Add cohort</button></div>{cohorts.map(c=><article className="cohort" key={c.id}><div><strong>{c.sequence_number}. {c.cohort_name}</strong><span>{c.planned_players} players · {c.status}</span></div><div><button disabled={current.status==="candidate"} onClick={()=>updateCohort(c.id,"active")}>Start</button><button onClick={()=>updateCohort(c.id,"paused")}>Pause</button><button onClick={()=>updateCohort(c.id,"completed")}>Complete</button></div></article>)}</section><section className="release-panel"><p className="eyebrow">Incident and rollback control</p><h2>Record launch issue</h2><label>Severity<select value={incident.severity} onChange={e=>setIncident({...incident,severity:e.target.value})}>{["low","medium","high","critical"].map(x=><option key={x}>{x}</option>)}</select></label><label>Summary<input value={incident.summary} onChange={e=>setIncident({...incident,summary:e.target.value})}/></label><label>Detail<textarea value={incident.detail} onChange={e=>setIncident({...incident,detail:e.target.value})}/></label><label className="tick"><input type="checkbox" checked={incident.rollback_required} onChange={e=>setIncident({...incident,rollback_required:e.target.checked})}/>Rollback review required</label><button className="primary-action" disabled={!incident.summary.trim()} onClick={addIncident}>Record incident</button>{incidents.map(i=><article className="incident" key={i.id}><span className={`incident-pill ${i.severity}`}>{i.severity}</span><strong>{i.summary}</strong><small>{i.status}{i.rollback_required?" · rollback review":""}</small></article>)}</section></div><section className="rollback-plan"><p className="eyebrow">Recorded rollback plan</p><p>{current.rollback_plan}</p></section></>}</AppShell>}
